-- Schede nuove dalle pagine RHS (controllo periodico del 24/11/2026): 29 specie del catalogo senza
-- nessuna scheda. Testi in italiano scritti a mano (scripts/rhs-import/dati/), in bozza e mostrate.
-- Generata da scripts/rhs-import/schede_nuove.py. Rollback: scripts/rhs-import/rollback_rhs_schede_nuove_lotto4.sql
do $$ begin
  if exists (select 1 from public.schede where taxon_id in ('2e0c360b-b4ca-4adb-a74f-1bc38891baf9'::uuid, '66d1eead-9d44-49e4-9ee2-131b9a85987f'::uuid, '91778e09-c539-486f-bfe1-732c9ed4c2aa'::uuid, '27729546-8532-408c-851d-7a2c7deae900'::uuid, '8b454ada-1b32-48e0-a5a3-e4de0bd038fb'::uuid, '6be0abfa-24f9-4f7e-9835-b4eef5161f59'::uuid, '67971d46-6e9a-4ceb-be45-874f8656c782'::uuid, '02170529-a3bd-49df-a991-3743710e2db2'::uuid, 'cc141372-403f-4c67-9a38-d56fee0b3b78'::uuid, '2d031800-0b6e-492d-8ab5-de7b96d86b6c'::uuid, '335460d4-ed3e-4a36-9615-2f4ba5f7f3b5'::uuid, '3bfcce97-4da5-422f-98fe-66470cddbbef'::uuid, '7e6d28b9-fbc6-416a-849b-56c16168c4fb'::uuid, 'ed8a3d31-acde-49d4-82e8-71c5679993d2'::uuid, '8d2e3968-adee-4448-8b19-1792c4e71318'::uuid, '8525d816-9bf0-4581-89fb-947e24577511'::uuid, '76a9e4ad-df0e-4e37-ac01-a85611899f8a'::uuid, 'f75318ed-ff71-42a9-aaa9-714aac4a48ba'::uuid, 'e46ba312-6bc9-48ea-9ace-c4879605df15'::uuid, '0966827f-71e8-4b9f-9503-6e30ebed67d9'::uuid, '75035ca1-5de2-4f02-92d1-5426a4e898bb'::uuid, '3f9473e2-7876-4f07-9db5-3d1cc9249444'::uuid, '8507522c-2451-4404-8232-be41dd188904'::uuid, '8995c2d1-c596-4327-b20e-633fef033c4b'::uuid, 'cb521d64-5c8a-4cd7-8d71-d777242e6528'::uuid, '64f53f4f-3fd0-4ff5-9314-c996db596f21'::uuid, 'f026da86-58a2-4218-a206-2531312e3cd3'::uuid, '766a0b39-5531-4f08-8c21-8fc71633507a'::uuid, '4240811e-8239-44b8-88a6-91a920197022'::uuid)) then
    raise exception 'una di queste specie ha già una scheda: lotto da rigenerare';
  end if;
end $$;
insert into public.schede (id, taxon_id, fonti, descrizione, descrizione_originale, lingua_descrizione, esigenze,
  ciclo_vitale, alert, stato_verifica, mostrata, forma, nota) values
('0aa578f4-4d74-5b45-af51-711b06286fa0'::uuid, '2e0c360b-b4ca-4adb-a74f-1bc38891baf9'::uuid, array['RHS (rhs.org.uk) — Acanthocalycium klimpelianum']::text[], 'Cactus della famiglia delle Cactacee, originario dell''Argentina, che nei vivai si trova anche come Acanthocalycium peitscherianum. Il fusto, da sferico a cilindrico, verde opaco, largo fino a 15 cm, ha fino a 20 coste con gruppi di spine lunghe e robuste. In estate porta fiori a trombetta viola chiaro, bianchi o rosa. Non regge il gelo: si coltiva in vaso, con un terriccio drenante arricchito di ghiaino, in pieno sole; si annaffia con moderazione durante la crescita, con due o tre concimazioni nella stagione, e pochissimo durante il riposo.', 'A spherical or cylindrical dull green stem up to 15cm thick with up to 20 ribs and clusters of long, strong spines. Trumpet-shaped pale purple, white or pink flowers are produced in summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme o staccando i polloni']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 184970'),
('4b98d77b-523c-5eed-bc05-2280180ccfa8'::uuid, '66d1eead-9d44-49e4-9ee2-131b9a85987f'::uuid, array['RHS (rhs.org.uk) — Angophora costata']::text[], 'Albero sempreverde della famiglia delle Mirtacee, originario dell''Australia orientale e parente stretto degli eucalipti, che in natura diventa molto grande. La corteccia liscia si sfoglia a chiazze e i fusti prendono colori dal rosa al grigio. Le foglie, coriacee e opposte, spuntano rosso porpora e diventano verde grigio, con il margine ondulato. In estate, quando la pianta ha raggiunto 2-3 m, porta mazzi arrotondati di fiori bianchi a cinque petali con stami sporgenti. Non regge il gelo: si coltiva in un grande vaso con terriccio drenante e sabbia, in piena luce, portandolo all''aperto in un posto soleggiato e riparato d''estate e al coperto d''inverno; si annaffia con moderazione durante la crescita e poco d''inverno.', 'An upright to spreading evergreen shrub or small tree with peeling bark and leathery, oval leaves in pairs, opening dark purple-red, maturing to grey-green with wavy edges. May flower in summer once it reaches 2-3m, producing rounded clusters of white, five-petalled flowers with prominent stamens', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 4-8m, diffusione 2.5-4m', 'Potatura: richiede poca potatura: si tolgono i rami secchi o rovinati, e in vaso si contengono le dimensioni accorciando i rami', 'Propagazione: per seme in primavera, trapiantando presto le piantine in vasetti singoli']::text[], 'bozza', true, 'albero', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 188382'),
('4b20c261-c945-5576-a487-6fc013f2ca99'::uuid, '91778e09-c539-486f-bfe1-732c9ed4c2aa'::uuid, array['RHS (rhs.org.uk) — Aspidistra caespitosa ''Jade Ribbons''']::text[], 'Pianta perenne sempreverde e rizomatosa della famiglia delle Asparagacee, originaria della Cina, parente della comune aspidistra. Forma cespi di foglie alte e strette, verde scuro, come nella varietà ''Jade Ribbons''. Di rado, tra la primavera e l''estate, porta a livello del terreno piccoli fiori a stella bianchi e rosso scuro. Si coltiva soprattutto in casa, in vasi grandi con un buon terriccio, ma nelle zone miti sta bene anche in giardino; sopporta l''ombra e un po'' di siccità. In casa cresce meglio con luce viva e filtrata e non sotto i 7 °C; si annaffia con moderazione durante la crescita, con due o tre concimazioni nella stagione. All''aperto vuole un terreno fresco ma ben drenato, fertile e sabbioso, con terra di foglie, all''ombra o a mezz''ombra in un posto riparato.', 'A clump-forming, rhizomatous, hardy evergreen perennial with tall, narrow dark green leaves.  Rarely, white and dark red, star-shaped flowers appear at the base of the plant in spring to summer.  Although most often grown as a houseplant, it is also a useful garden plant in mild areas, and is tolerant of shade and drier conditions', 'it', '{"luce": "Ombra piena, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose, ragnetto rosso, cocciniglie e larve di oziorrinco; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 151236'),
('81de5f21-c259-52eb-8af3-7ca51ef76b69'::uuid, '27729546-8532-408c-851d-7a2c7deae900'::uuid, array['RHS (rhs.org.uk) — Aspidistra linearifolia ''Leopard''']::text[], 'Pianta perenne sempreverde e rizomatosa della famiglia delle Asparagacee, originaria della Cina, parente della comune aspidistra. Forma cespi di foglie lunghe, strette e lanceolate, verde scuro e lucide; nella varietà ''Leopard'' sono punteggiate di grandi macchie giallo oro. Di rado, tra la primavera e l''estate, porta a livello del terreno piccoli fiori a stella verde giallo con il centro porpora, poco vistosi. Si coltiva soprattutto in casa, in vasi grandi con un buon terriccio, ma nelle zone miti sta bene anche in giardino; sopporta l''ombra e un po'' di siccità. In casa cresce meglio con luce viva e filtrata e non sotto i 7 °C; si annaffia con moderazione durante la crescita, con due o tre concimazioni nella stagione: le varietà variegate, concimate troppo, tornano verdi. All''aperto vuole un terreno fresco ma ben drenato, fertile e sabbioso, all''ombra o a mezz''ombra in un posto riparato.', 'A clump-forming, rhizomatous, hardy evergreen perennial with long, narrow, broadly lance-shaped glossy dark green leaves with large golden-yellow spots.  Rarely, small, inconspicuous star-shaped green-yellow flowers with purple centres appear at the base of the plant in spring to summer.  Although most often grown as a houseplant, it is also a useful garden plant in mild areas, and is tolerant of shade and drier conditions', 'it', '{"luce": "Ombra piena, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose, ragnetto rosso, cocciniglie e larve di oziorrinco; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 175141'),
('9e2b6f72-5d3c-533a-8600-0962af5522ec'::uuid, '8b454ada-1b32-48e0-a5a3-e4de0bd038fb'::uuid, array['RHS (rhs.org.uk) — Aspidistra saxicola ''Uan Fat Lady''']::text[], 'Pianta perenne sempreverde e rizomatosa della famiglia delle Asparagacee, originaria della Cina meridionale, più piccola e compatta della comune aspidistra. Si coltiva per le foglie lucide, verde scuro, lunghe fino a 20 cm, che nella varietà ''Uan Fat Lady'' hanno il centro più chiaro e piccole macchie giallastre. È un''ottima pianta da appartamento perché sopporta l''ombra, gli sbalzi di temperatura e un po'' di trascuratezza, ma nelle zone miti si può tenere anche in giardino. In casa cresce meglio con luce viva e filtrata e non sotto i 7 °C; si annaffia con moderazione durante la crescita, con due o tre concimazioni nella stagione. All''aperto vuole un terreno fresco ma ben drenato, fertile e sabbioso, all''ombra o a mezz''ombra in un posto riparato.', 'A compact, rhizomatous perennial grown for its glossy, dark green leaves (to 20cm), which have paler central markings and yellowish flecks. It makes a good houseplant due to its tolerance of shade, fluctuating temperatures and neglect, but can also be grown as a garden plant', 'it', '{"luce": "Ombra piena, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose, ragnetto rosso, cocciniglie e larve di oziorrinco; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 191052'),
('708bd82f-b904-5030-917d-4d19cd95293e'::uuid, '6be0abfa-24f9-4f7e-9835-b4eef5161f59'::uuid, array['RHS (rhs.org.uk) — Catalpa fargesii f. duclouxii']::text[], 'Albero deciduo della famiglia delle Bignoniacee, originario della Cina occidentale, che matura in una chioma arrotondata alta 8-12 m. Le foglie sono grandi, intere e appuntite, sfumate di bronzo in primavera. A inizio estate porta pannocchie di fiori a trombetta rosa pallido, con la gola macchiata di bruno e arancio, a cui seguono lunghi baccelli sottili simili a fagiolini. La forma più coltivata, duclouxii, è particolarmente fiorifera. Vuole un terreno fertile, fresco ma ben drenato, al sole o a mezz''ombra, e un posto riparato dai venti forti, che lacerano le grandi foglie; da giovane va protetta dalle gelate tardive.', 'A good flowering form bearing panicles of trumpet-shaped flowers of pale pink, with brown and orange-spotted throats. These are followed by narrow bean-like seed pods. Large, simple, pointed leaves are tinged bronze in spring. Matures to a round-crowned tree up to 8m in height', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a tracheoverticillosi e, raramente, ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 8-12m, diffusione 4-8m', 'Potatura: come albero richiede pochissima potatura, solo i rami secchi o rovinati; coltivata come arbusto per il fogliame si taglia ogni anno a fine inverno vicino alla base', 'Propagazione: per talee erbacee in estate o per innesto a gemma a fine estate']::text[], 'bozza', true, 'albero', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 94762'),
('dd9da407-e03b-57ea-a426-43ab51db0fe8'::uuid, '67971d46-6e9a-4ceb-be45-874f8656c782'::uuid, array['RHS (rhs.org.uk) — Clianthus maximus ''Roseus''']::text[], 'Arbusto sempreverde della famiglia delle Fabacee, originario della Nuova Zelanda, dove è raro in natura; nei vivai si trova spesso come Clianthus maximus ed è chiamato becco di pappagallo per la forma dei fiori. I fusti lunghi e flessibili si appoggiano ai sostegni fino a 4 m e portano foglie pennate verde scuro, lunghe fino a 15 cm, con 13-25 foglioline. Tra la tarda primavera e l''inizio dell''estate pendono grappoli di 15 fiori ricurvi ad artiglio, lunghi 7 cm, rosso vivo o rosa intenso a seconda della varietà. Vuole pieno sole e un terreno ben drenato, contro un muro esposto a sud o a ovest con fili o un graticcio a cui legarlo; d''inverno una spessa pacciamatura asciutta protegge le radici dal freddo.', 'An evergreen shrub with climbing stems up to 4m high, dark green pinnate leaves up to 15cm long and made up of 13 to 25 leaflets. Hanging clusters of up to 15 deep pink, claw-like flowers, each 7cm long, appear in late spring and early summer', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetto a ragnetto rosso e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -5 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: a inizio estate, dopo la fioritura, si tolgono i rami secchi e si accorciano di un terzo al massimo quelli che hanno fiorito, così da preparare la struttura per l''anno dopo', 'Propagazione: per talee semilegnose in estate']::text[], 'bozza', true, 'rampicante', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 321913'),
('8437ee1d-d682-52ad-a9af-8aa61c59cd4f'::uuid, '02170529-a3bd-49df-a991-3743710e2db2'::uuid, array['RHS (rhs.org.uk) — Clusia major ''Princess''']::text[], 'Arbusto o piccolo albero sempreverde della famiglia delle Clusiacee, originario dei Caraibi, in natura semiepifita: spesso nasce sugli altri alberi e scende con le radici fino a terra. Raggiunge circa 3 m, molto meno in vaso, e ha foglie spesse, coriacee e lucide e fusti robusti. In estate le piante adulte portano fiori a imbuto bianchi o rosa, che in vaso si vedono di rado. In casa vuole luce viva ma filtrata, senza sole cocente, e un terriccio drenante con terra di foglie e ghiaino; si annaffia abbondantemente d''estate, con un concime equilibrato ogni settimana durante la crescita, e si tiene appena umida d''inverno. Non va rinvasata spesso: soffre se si disturbano le radici.', 'A semi-epiphytic, tropical shrub or small tree to 3m tall, considerably less when grown as a houseplant. It has particularly thick, glossy leaves and stout stems. Funnel-shaped, white or pink flowers are produced in the summer on mature plants, but are unlikely to be seen on potted specimens', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: al riparo può essere soggetta a ragnetto rosso, cocciniglie e cocciniglie farinose; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 15 °C', 'Potatura: richiede poca potatura; accorciare i rami la fa ramificare e la rende più folta', 'Propagazione: per talee erbacee con calore dal fondo in estate, o per margotta in primavera o in estate']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 191575'),
('3bec7b0e-82ac-5d0f-bb0f-c29e9591f816'::uuid, 'cc141372-403f-4c67-9a38-d56fee0b3b78'::uuid, array['RHS (rhs.org.uk) — Corylopsis platypetala']::text[], 'Arbusto deciduo della famiglia delle Amamelidacee, originario della Cina, che con gli anni può superare i 4 m. Le foglie sono largamente ovali, verde scuro sopra e grigio azzurro sotto. In primavera, sui rami ancora spogli, pendono corti grappoli di fiori giallo pallido e profumati, lunghi fino a 4 cm. Ama la mezz''ombra e il terreno acido; le gelate tardive possono rovinare i fiori, per cui va messo in un punto riparato.', 'A large, deciduous shrub to 6m in height, with broadly oval leaves, blue-grey beneath and dark green above.  Fragrant, pale-yellow flowers in drooping racemes to 4cm in length are borne on bare stems in spring', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 1.5-2.5m', 'Potatura: richiede pochissima potatura: subito dopo la fioritura si tolgono i rami secchi o rovinati', 'Propagazione: per seme in vaso in autunno in un cassone aperto, per talee erbacee in estate o per margotta in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 96316'),
('4e7a5374-010f-560a-85a1-b37842f78393'::uuid, '2d031800-0b6e-492d-8ab5-de7b96d86b6c'::uuid, array['RHS (rhs.org.uk) — Potentilla glabra var. veitchii']::text[], 'Arbusto deciduo o semisempreverde della famiglia delle Rosacee, parente della comune potentilla arbustiva e noto nei vivai come Potentilla veitchii. Compatto e cespuglioso, raggiunge circa un metro in altezza e larghezza e ha piccole foglie pennate verde grigio. Da giugno a ottobre si copre di fiori bianchi a coppa, larghi fino a 2,5 cm, con il centro giallo. Molto rustico e di poche pretese, cresce in quasi ogni terreno ben drenato, anche calcareo o argilloso, purché in pieno sole.', 'A compact, bushy, deciduous shrub with small grey-green pinnate leaves reaching a height and spread of 1m.  Masses of saucer-shaped white flowers to 2.5cm across with yellow centres appear from June to October', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: a fine inverno si accorciano i rami dell''anno prima e si tolgono quelli vecchi o deboli, per tenerlo compatto e fiorito', 'Propagazione: per seme o per talee semilegnose']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 21883'),
('23a5372e-61a5-5822-90a1-12b48430532a'::uuid, '335460d4-ed3e-4a36-9615-2f4ba5f7f3b5'::uuid, array['RHS (rhs.org.uk) — Disporum kawakamii ''Night Heron''']::text[], 'Pianta perenne rizomatosa della famiglia delle Colchicacee, originaria di Taiwan, che forma cespi di steli alti e arcuati con foglie lucide. Nella varietà ''Night Heron'', la più diffusa, le foglie spuntano porpora scuro e diventano lentamente verdi durante la stagione. A fine primavera porta delicati fiori a campanella, bianchi o giallini, seguiti da bacche rosso nerastre. È una pianta da ombra: vuole un posto fresco e a mezz''ombra, con un terreno ricco di humus, fresco ma ben drenato, acido o neutro.', 'A clump-forming, rhizomatous perennial with tall, arching stems, and purple, glossy leaves which gradually turn to green throughout the season.  It produces delicate bell-shaped white to yellow flowers in late spring, followed by black-red berries.  A good plant for shady areas', 'it', '{"luce": "Mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: i germogli giovani possono essere attaccati da lumache e limacce, ma in genere è esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Potatura: in primavera si tolgono i vecchi steli prima che spuntino i nuovi germogli', 'Propagazione: per seme o per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 282669'),
('421b25e7-ebc5-5abe-b050-8f0ad84c34c0'::uuid, '3bfcce97-4da5-422f-98fe-66470cddbbef'::uuid, array['RHS (rhs.org.uk) — Anemone scabiosa']::text[], 'Pianta erbacea perenne della famiglia delle Ranuncolacee, originaria della Cina e coltivata da secoli in Giappone: è uno degli anemoni giapponesi, nota a lungo come Anemone hupehensis var. japonica e, nei vivai, anche come Anemone scabiosa o Anemone nipponica. Forma cespi di foglie verde medio, dentate e divise in tre lobi, da cui dall''estate al tardo autunno si alzano steli ramificati ed eleganti, fino a un metro, con grandi fiori semplici o doppi, bianchi o di varie tonalità di rosa, con il centro giallo. Rustica e longeva, si espande lentamente con le radici. Vuole un terreno ricco di humus, fresco ma ben drenato, senza ristagni d''acqua in inverno, al sole o a mezz''ombra.', 'A branching, tall and graceful herbaceous perennial with mid-green toothed leaves which are divided into three lobes.  Has large double or single flowers with a yellow centre in different shades of pink and white from summer to late autumn.', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a nematodi delle foglie e delle gemme, bruchi e lumache; Malattie: può essere soggetta a oidio e al carbone degli anemoni', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: dopo la fioritura si tagliano i vecchi steli', 'Propagazione: per divisione a inizio primavera o in autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 171956'),
('40a55dc9-ff56-508c-8356-91409eb9042e'::uuid, '7e6d28b9-fbc6-416a-849b-56c16168c4fb'::uuid, array['RHS (rhs.org.uk) — Leptinella pusilla ''Platt''s Black''']::text[], 'Pianta perenne tappezzante della famiglia delle Asteracee, originaria della Nuova Zelanda, che forma tappeti bassissimi di piccole foglie simili a fronde di felce; nella varietà ''Platt''s Black'', la più coltivata, sono bronzo nerastro con le punte verdi. In estate porta capolini minuti e poco vistosi, verde giallastri. Vuole un terreno ben drenato che però non si secchi, al sole o a mezz''ombra. È ideale sui muretti e tra le lastre dei vialetti, ma si allarga con vigore e negli spazi aperti può diventare invadente.', 'A low, mat-forming perennial with small, fern-like leaves that are bronzy-black with green tips. Insignificant yellowish-green flowers appear in summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 138742'),
('43558950-f4c6-5aad-9883-eff253b94a87'::uuid, 'ed8a3d31-acde-49d4-82e8-71c5679993d2'::uuid, array['RHS (rhs.org.uk) — Mertensia simplicissima']::text[], 'Pianta perenne della famiglia delle Boraginacee, delle coste sabbiose e ghiaiose dell''Asia nordorientale, che nei vivai si trova anche come Mertensia asiatica. Si allarga prostrata sul terreno con foglie carnose verde azzurro, lunghe fino a 10 cm. A inizio estate porta mazzetti ramificati di fiori a campanella azzurro vivo, che si aprono da boccioli rosa. Vuole un terreno sabbioso e ghiaioso, molto drenante e povero, in pieno sole con un po'' d''ombra nelle ore più calde: è adatta al giardino roccioso e ai vasi di ghiaia. Le lumache ne sono ghiotte.', 'A spreading, prostrate perennial with fleshy, blue-grey-green leaves, up to 10cm long, and branched clusters of bright blue, bell-shaped flowers opening from pink buds in early summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: si accorcia dopo la fioritura', 'Propagazione: per seme in vasetti in cassone freddo in autunno, tenendo le piantine all''ombra e il terriccio sempre appena umido, o per divisione delicata all''inizio della ripresa vegetativa in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 59331'),
('d273c043-378a-5f54-86bb-18847ed752a6'::uuid, '8d2e3968-adee-4448-8b19-1792c4e71318'::uuid, array['RHS (rhs.org.uk) — Molinia litoralis']::text[], 'Graminacea perenne della famiglia delle Poacee, diffusa nell''Europa occidentale e a lungo considerata una sottospecie della comune Molinia caerulea, da cui si distingue per la taglia più grande. Forma cespi di foglie lineari e arcuate da cui in estate si alzano steli fino a 1,5 m con leggere pannocchie di piccoli fiori violacei, trasparenti al vento. In autunno foglie e steli diventano giallo dorato e restano decorativi fino all''inverno. Molto rustica, cresce in ogni terreno fresco ma ben drenato, meglio se acido, al sole o a mezz''ombra.', 'A tussocky, deciduous grass with arching, linear leaves that turn yellow in autumn, and fine sprays of small, purplish flowers in summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 1-1.5m, diffusione 0.5-1m', 'Potatura: in primavera si tagliano alla base il fogliame secco e i vecchi steli fioriti', 'Propagazione: per divisione in primavera, o per seme in vaso in cassone freddo in primavera']::text[], 'bozza', true, 'graminacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 70206'),
('edd6c1ac-a762-59d1-bfbe-479208c659cd'::uuid, '8525d816-9bf0-4581-89fb-947e24577511'::uuid, array['RHS (rhs.org.uk) — Bartsia odontites']::text[], 'Pianta annuale della famiglia delle Orobancacee, diffusa in tutta Europa nei prati, lungo le strade e nei campi incolti, nota anche come perlina rossa. Ha fusti sottili, eretti, ramificati e pubescenti, alti fino a 50 cm, con foglie da oblunghe a lanceolate, dentate, lunghe al più 3 cm. In estate porta spighe di piccoli fiori rosa a due labbra. È una semiparassita: produce clorofilla ma integra il nutrimento attaccandosi alle radici delle graminacee vicine, per cui si semina nei prati fioriti, dove frena le erbe più vigorose e lascia spazio ai fiori. Cresce meglio in pieno sole e in terreni ben drenati e poco fertili.', 'An annual to 50cm tall with slender, upright, branched and downy stems bearing oblong to lance-shaped, toothed leaves up to 3cm long and pink, two-lipped flowers in summer. Commonly found growing wild in grasslands, this annual is semi-parasitic on grass roots', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'annuale', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme, sparso direttamente nel prato']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 156883'),
('4f80046e-2bfb-5a49-b9ad-0421e591a195'::uuid, '76a9e4ad-df0e-4e37-ac01-a85611899f8a'::uuid, array['RHS (rhs.org.uk) — Physocarpus ribesifolius ''Aureus''']::text[], 'Arbusto deciduo della famiglia delle Rosacee, originario della Russia orientale, della Cina nordorientale e della Corea, che nei vivai si trova anche come Physocarpus ribesifolius. Forma folti cespugli di fusti alti fino a 3 m, con foglie a tre lobi simili a quelle dell''acero; nella varietà ''Aureus'' spuntano gialle. In estate porta mazzetti tondeggianti di piccoli fiori bianchi sfumati di rosa, a cui seguono piccoli frutti rigonfi come vesciche. Molto rustico, preferisce un terreno acido, mediamente fertile e ricco di humus, ma regge anche quelli calcarei; nei suoli calcarei poco profondi le foglie possono ingiallire.', 'A deciduous shrub forming an extensive thicket of stems to 3m tall, bearing maple-like, 3-lobed leaves, yellow when young, and rounded clusters of small pink-tinged white flowers in summer, followed by small bladdery fruits', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Argilloso, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetto ad armillaria', 'Rusticità: minime anche sotto i -20 °C', 'Dimensioni a maturità: altezza 2.5-4m, diffusione 2.5-4m', 'Potatura: dopo la fioritura si accorciano i rami che hanno fiorito e si diradano i fusti, togliendo alla base i più vecchi', 'Propagazione: per talee erbacee in estate, o trapiantando in vaso i polloni radicati in autunno o in primavera']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 66614'),
('86234134-0348-5680-ae7f-ec0559225e20'::uuid, 'f75318ed-ff71-42a9-aaa9-714aac4a48ba'::uuid, array['RHS (rhs.org.uk) — Centaurea hypoleuca ''John Coutts''']::text[], 'Pianta erbacea perenne della famiglia delle Asteracee, originaria del Caucaso e della Turchia, nota nei vivai come Centaurea hypoleuca, soprattutto con la varietà ''John Coutts''. Vigorosa, ha foglie frastagliate e lobate, bianche e feltrose sulla pagina inferiore. In estate, e spesso fino all''inizio dell''autunno, porta vistosi capolini rosa porpora larghi 6 cm, molto visitati da api e farfalle. Vuole un terreno ben drenato e il pieno sole.', 'A vigorous herbaceous perennial, with jagged lobed leaves white-felted beneath, and showy purplish-pink flower-heads 6cm across in summer and often into early autumn', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: può essere soggetta a oidio', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme in vaso in cassone freddo in primavera, o per divisione in primavera o in autunno']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 96985'),
('deb1c2fa-3aa5-5c81-bd24-c5fbe38020b4'::uuid, 'e46ba312-6bc9-48ea-9ace-c4879605df15'::uuid, array['RHS (rhs.org.uk) — Graptopetalum pentandrum ''Superbum''']::text[], 'Succulenta perenne e sempreverde della famiglia delle Crassulacee, originaria del Messico, nota nei vivai come Graptopetalum pentandrum, soprattutto con la varietà ''Superbum''. Forma cespi alti una ventina di centimetri di rosette basse e ramificate, con foglie carnose rosa porpora e argentate. In primavera porta fiori a stella bianco giallastri. Non regge il gelo: si coltiva in vaso, con un terriccio drenante, in piena luce; si annaffia abbondantemente in primavera e in estate, con un concime liquido povero di azoto una volta al mese, e si tiene appena umida in autunno e in inverno.', 'An evergreen, clump-forming, perennial succulent to around 20cm high with low-growing rosettes of silvery purple-pink succulent leaves which branch outwards.  Star-shaped yellow-white flowers appear in spring', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per talea di foglia, il modo più semplice, o staccando i polloni']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 268551'),
('b2b43714-d510-57f4-8626-0ec171403252'::uuid, '0966827f-71e8-4b9f-9503-6e30ebed67d9'::uuid, array['RHS (rhs.org.uk) — Sagina glabra ''Aurea''']::text[], 'Piccola perenne sempreverde della famiglia delle Cariofillacee, originaria delle montagne dell''Europa meridionale, che forma cuscini fitti di fusti sottili e foglie lineari finissime. In estate porta minuscoli fiori bianchi su steli alti al più 4 cm. La varietà più coltivata, ''Aurea'', ha foglie verde giallo. Regge un leggero calpestio e si usa tra le lastre dei vialetti, nel giardino roccioso, nelle vaschette di pietra e come piccolo prato poco calpestato. Vuole un terreno mediamente fertile, da acido a neutro, al sole con un po'' d''ombra nelle ore più calde: teme il caldo intenso, la siccità e i ristagni d''acqua, e con troppa ombra si allunga.', 'A low-growing evergreen perennial, forming dense mats of slender stems with fine, linear, yellow-green leaves. Tiny white flowers are held up on stems to 4cm high in summer', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta ad afidi e, al riparo, a ragnetto rosso; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; si può rifilare ai bordi dei vialetti per tenerli ordinati', 'Propagazione: per seme in vaso in autunno, o per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 85024'),
('59845de5-e84e-508c-aa97-d9825043fe1a'::uuid, '75035ca1-5de2-4f02-92d1-5426a4e898bb'::uuid, array['RHS (rhs.org.uk) — Satureja subspicata']::text[], 'Piccolo suffrutice sempreverde della famiglia delle Lamiacee, originario dei Balcani, alto circa 20 cm, con fusti sottili ed eretti e foglie lineari, coriacee e molto aromatiche. A fine estate porta verticilli di fiori tubolari viola. Le foglie si usano fresche o secche in cucina, come quelle della santoreggia. Vuole un terreno mediamente fertile e ben drenato, da neutro a leggermente calcareo, in pieno sole, e va protetta dall''eccesso di umidità in inverno.', 'An evergreen subshrub to 20cm tall, with slender, upright stems bearing strongly aromatic, leathery, linear leaves. In late summer it produces whorls of tubular, purple flowers. The leaves are used fresh and dried as a culinary herb', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: dopo la fioritura si spunta per mantenerla compatta', 'Propagazione: per seme o per talee erbacee']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 218670'),
('3baaca55-3c88-5a69-ad89-beec3b7b572e'::uuid, '3f9473e2-7876-4f07-9db5-3d1cc9249444'::uuid, array['RHS (rhs.org.uk) — Skimmia reevesiana']::text[], 'Arbusto sempreverde della famiglia delle Rutacee, originario della Cina, compatto e basso, raramente oltre il metro. Le foglie coriacee, verde scuro, sono appena aromatiche. In primavera porta fitte pannocchie coniche di piccoli fiori bianco crema e profumati, a cui seguono in autunno bacche rosse che spesso restano sulla pianta fino alla primavera dopo. A differenza della più comune Skimmia japonica, che ha piante maschili e femminili separate, ha fiori ermafroditi e fruttifica anche da sola. Ama l''ombra o la mezz''ombra e un terreno fresco, ricco di humus e ben drenato; regge l''inquinamento e un po'' di trascuratezza, ma al sole pieno e nei terreni poveri e asciutti le foglie ingialliscono.', 'A compact, evergreen shrub with slightly aromatic, leathery leaves. Small, fragrant, creamy-white flowers are produced in dense, conical clusters in spring, followed by red berries in autumn which often remain until the following spring', 'it', '{"luce": "Ombra piena, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Argilloso, franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie e, in vaso, a oziorrinco; Malattie: può essere soggetta a marciume radicale da Phytophthora e ad armillaria', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.5-1m, diffusione 0.5-1m', 'Potatura: richiede pochissima potatura: dopo la fioritura si tolgono i rami secchi o rovinati e si accorcia appena qualche ramo fuori forma', 'Propagazione: per talee semilegnose a fine estate, o per seme in vasetti all''aperto in autunno']::text[], 'bozza', true, 'arbusto', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 17410'),
('eea59574-21fd-534d-9601-6449c6687897'::uuid, '8507522c-2451-4404-8232-be41dd188904'::uuid, array['RHS (rhs.org.uk) — Stachys aethiopica ''Danielle''']::text[], 'Pianta erbacea perenne della famiglia delle Lamiacee, originaria dell''Africa meridionale, che forma cespi compatti alti fino a 30 cm. Le foglie dentate, disposte a coppie, profumano se strofinate. Tra metà e fine estate porta spighe erette con verticilli di fiori rosa scuro, come nella varietà ''Danielle''. Cresce in qualsiasi terreno mediamente fertile, fresco ma ben drenato, al sole o a mezz''ombra; nelle zone più fredde va riparata dal gelo intenso.', 'A clump-forming, herbaceous perennial to 30cm tall, with alternate pairs of toothed leaves; the foliage is aromatic when crushed. In mid and late summer, dark pink flowers are carried in whorls on upright flowerspikes', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Umido ma ben drenato", "terreno": "Calcareo, franco, sabbioso, argilloso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: generalmente esente da parassiti; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per divisione']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 175018'),
('f4a8e98f-72f2-5c46-8590-1aaaf2dd328a'::uuid, '8995c2d1-c596-4327-b20e-633fef033c4b'::uuid, array['RHS (rhs.org.uk) — Stachys minor ''Saharan Pink''']::text[], 'Pianta perenne della famiglia delle Lamiacee che forma cespi compatti di foglie dal margine smerlato. In estate e fino all''inizio dell''autunno si alzano steli eretti, alti fino a 40 cm, con spighe fitte di fiori rosa: la varietà più diffusa è ''Saharan Pink''. Vuole un terreno ben drenato, al sole o a mezz''ombra leggera, e teme l''umidità invernale.', 'A clump-forming perennial to 40cm, with scalloped leaves and upright stems of dense, terminal spikes of pink flowers appearing in summer and early autumn', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: togliere i fiori appassiti prolunga la fioritura', 'Propagazione: per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 210716'),
('00e71c20-e7e5-5d8f-8393-613d95e75dc3'::uuid, 'cb521d64-5c8a-4cd7-8d71-d777242e6528'::uuid, array['RHS (rhs.org.uk) — Strobilanthes atropurpurea Nees']::text[], 'Pianta perenne della famiglia delle Acantacee, originaria dell''Himalaya e della Cina, con la base legnosa e radici che si allargano lentamente. I fusti eretti e angolosi, alti circa 50 cm, portano coppie di foglie verdi, da ellittiche a lanceolate, dal margine seghettato. A fine estate porta fiori tubolari blu porpora, ricurvi in punta, da soli o a coppie. Vuole un terreno leggero, fertile e ben drenato, al sole o a mezz''ombra; in inverno le giova una pacciamatura.', 'An upright perennial to around 50cm high, with a woody base, gently creeping roots, and slender, angled stems bearing pairs of elliptic to lance-shaped green leaves with serrated edges. In late summer, tubular purple-blue flowers, curved over at the tips, are borne singly or in pairs on leafy stems', 'it', '{"luce": "Pieno sole, mezz''ombra", "acqua": "Ben drenato", "terreno": "Franco; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a ragnetto rosso; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura', 'Propagazione: per seme in primavera a 13-18 °C, o per talee basali o erbacee in primavera o a inizio estate, con calore dal fondo']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 178632'),
('174aba43-26a4-5181-823c-badb4564e48d'::uuid, '64f53f4f-3fd0-4ff5-9314-c996db596f21'::uuid, array['RHS (rhs.org.uk) — Aster yunnanensis ''Napsbury''']::text[], 'Pianta perenne della famiglia delle Asteracee, originaria delle montagne della Cina sudoccidentale e del Tibet, nota nei vivai come Aster yunnanensis, soprattutto con la varietà ''Napsbury''. Forma tappeti di foglie lanceolate, verde scuro e pelose, da cui a inizio estate si alzano steli alti fino a 30 cm con capolini simili a margherite: sottili petali blu violetto attorno a un centro giallo arancio. Vuole un terreno mediamente fertile e ben drenato, in pieno sole e in posizione aperta.', 'A mat-forming, deciduous perennial to 30cm tall with dark green, hairy, lance-shaped leaves. Daisy-like single flower-heads comprise violet-blue, narrow, delicate rays surrounding a contrasting orange-yellow centre, in early summer', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a lumache, limacce, nematodi delle foglie e delle gemme e afidi; Malattie: può essere soggetta ad avvizzimenti, maculature fogliari e muffa grigia', 'Rusticità: minime fino a -20 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.5-1m', 'Potatura: si accorcia dopo la fioritura', 'Propagazione: per seme in vaso in cassone freddo in primavera o in autunno, o per divisione in primavera']::text[], 'bozza', true, 'erbacea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 27421'),
('a19e63d5-b885-5d3e-a661-adf0c8fe3db1'::uuid, 'f026da86-58a2-4218-a206-2531312e3cd3'::uuid, array['RHS (rhs.org.uk) — Tristagma ''Rolf Fiedler''']::text[], 'Genere di piccole bulbose della famiglia delle Amarillidacee, originarie del Sud America, parenti di Ipheion, con cui alcune specie e varietà vengono ancora confuse nei vivai: tra queste l''ibrido ''Rolf Fiedler''. Formano ciuffi di foglie strette e verde chiaro e, in primavera, steli eretti con fiori solitari a stella, profumati, larghi 3-4 cm, di un azzurro intenso con una linea scura al centro di ogni petalo. I bulbi si piantano in autunno a circa 8 cm di profondità, in un terreno mediamente fertile, ricco di humus e ben drenato che non si secchi del tutto, in pieno sole; nelle zone fredde si proteggono in inverno con una pacciamatura.', 'A perennial forming a clump of narrow light green leaves, with erect stems bearing fragrant, solitary, starry, clear deep blue flowers 3-4cm in width, each petal with a dark central line', 'it', '{"luce": "Pieno sole", "acqua": "Umido ma ben drenato, ben drenato", "terreno": "Calcareo, argilloso, franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a lumache e limacce; Malattie: generalmente esente da malattie', 'Rusticità: minime fino a -10 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme in vaso in cassone freddo appena maturo, o per divisione in estate durante il riposo']::text[], 'bozza', true, 'bulbosa', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 65436'),
('269b33f2-fc15-5322-ba74-d786d707be40'::uuid, '766a0b39-5531-4f08-8c21-8fc71633507a'::uuid, array['RHS (rhs.org.uk) — Rebutia pulchra']::text[], 'Piccolo cactus della famiglia delle Cactacee, originario della Bolivia, noto finora nei vivai come Rebutia pulchra o Sulcorebutia: oggi i botanici vi riuniscono diverse forme vicine, tra cui Sulcorebutia rauschii e Sulcorebutia crispata. Forma colonie fitte di fusti globosi alti fino a 5 cm, verdi o sfumati di porpora, coperti di spine bianche, setolose e ricurve. A fine primavera porta fiori a imbuto arancio vivo, rosa o rossi, spesso con la gola di un altro colore. Si coltiva in vaso, in un terriccio per cactacee, in pieno sole e in un luogo ben aerato; si annaffia con moderazione durante la crescita, con un concime per cactus una volta al mese, e si lascia quasi asciutto nel resto dell''anno. Va riparato dal gelo.', 'A clustering cactus forming a dense colony of globose, green to purple-flushed stems to 5cm tall. Bristly, white, recurved radial spines arise from each areole. In late spring, funnel-shaped bright orange, pink or red flowers may be produced, often with a contrasting eye', 'it', '{"luce": "Pieno sole", "acqua": "Ben drenato", "terreno": "Franco, sabbioso; pH acido, alcalino, neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetto a cocciniglie farinose; Malattie: con troppa umidità può essere soggetto a marciumi delle radici e del fusto', 'Rusticità: minime non sotto 1 °C', 'Dimensioni a maturità: altezza fino a 0.1m, diffusione 0-0.1m', 'Potatura: non richiede potatura', 'Propagazione: per seme a inizio primavera, a circa 21 °C, o staccando i polloni in primavera o in estate']::text[], 'bozza', true, 'succulenta', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 269091'),
('38ba941b-f3e9-5930-ab07-8f6cf629f10c'::uuid, '4240811e-8239-44b8-88a6-91a920197022'::uuid, array['RHS (rhs.org.uk) — ×Colmanara ''Massai Red''']::text[], 'Genere ibrido di orchidee della famiglia delle Orchidacee, creato in coltura incrociando specie dei generi Oncidium e Miltonia; nei vivai molte di queste piante si trovano ancora con il vecchio nome di Colmanara. Sono orchidee epifite di media taglia, sempreverdi, che formano cespi di pseudobulbi ovali e un po'' appiattiti, organi di riserva per l''acqua e il nutrimento, da cui partono foglie nastriformi lunghe 30-40 cm. Dalla base degli pseudobulbi maturi nascono steli eretti fino a 60 cm con molti fiori di 3-4 cm, rosso scuro, oppure giallo pallido macchiati di bruno, con il labello bianco o cremisi. In casa vogliono luce viva ma filtrata, mai il sole diretto né il calore di un termosifone, con almeno 13-15 °C di notte e non oltre 25 °C di giorno. Si coltivano in un substrato per orchidee a base di corteccia, alleggerito con ghiaino e sfagno o fibra di cocco, e si annaffiano quando il vaso diventa leggero, senza lasciarle mai nell''acqua; d''inverno si danno meno acqua e meno concime. Crescono meglio un po'' strette nel vaso: si rinvasano solo ogni 2-3 anni.', 'A medium-sized, epiphytic orchid with strap-shaped, 30-40cm long, evergreen leaves. New growth appears from the swollen stem base - pseudobulb, a storage organ for water and nutrients. They are oval-shaped, slightly flattened around the top, and partially covered by two pairs of green, leafed sheaths. New flowering stems arise from the axils of young, mature pseudobulbs and the leafed sheaths. Up to 60cm long, upright flowering stems carry 15-20 flowers. Each flower is 4cm large, with dark red petals and sepals, and crimson, sometimes white-margined lip and contrasting white column.', 'it', '{"luce": "Mezz''ombra", "acqua": "Ben drenato", "terreno": "pH neutro"}'::jsonb, 'perenne', array['Parassiti: può essere soggetta a cocciniglie farinose, afidi e cocciniglie; Malattie: generalmente esente da malattie', 'Rusticità: minime non sotto i 15 °C', 'Dimensioni a maturità: altezza 0.1-0.5m, diffusione 0.1-0.5m', 'Potatura: non richiede potatura; a fioritura finita si taglia lo stelo fiorale', 'Propagazione: per divisione delle piante adulte quando riempiono il vaso, lasciando a ogni porzione almeno tre pseudobulbi vecchi']::text[], 'bozza', true, 'orchidea', 'controllo periodico RHS del 24/11/2026, schede nuove; pagina RHS 275774');
do $$ declare n int; begin
  select count(*) into n from public.schede where id in ('0aa578f4-4d74-5b45-af51-711b06286fa0'::uuid, '4b98d77b-523c-5eed-bc05-2280180ccfa8'::uuid, '4b20c261-c945-5576-a487-6fc013f2ca99'::uuid, '81de5f21-c259-52eb-8af3-7ca51ef76b69'::uuid, '9e2b6f72-5d3c-533a-8600-0962af5522ec'::uuid, '708bd82f-b904-5030-917d-4d19cd95293e'::uuid, 'dd9da407-e03b-57ea-a426-43ab51db0fe8'::uuid, '8437ee1d-d682-52ad-a9af-8aa61c59cd4f'::uuid, '3bec7b0e-82ac-5d0f-bb0f-c29e9591f816'::uuid, '4e7a5374-010f-560a-85a1-b37842f78393'::uuid, '23a5372e-61a5-5822-90a1-12b48430532a'::uuid, '421b25e7-ebc5-5abe-b050-8f0ad84c34c0'::uuid, '40a55dc9-ff56-508c-8356-91409eb9042e'::uuid, '43558950-f4c6-5aad-9883-eff253b94a87'::uuid, 'd273c043-378a-5f54-86bb-18847ed752a6'::uuid, 'edd6c1ac-a762-59d1-bfbe-479208c659cd'::uuid, '4f80046e-2bfb-5a49-b9ad-0421e591a195'::uuid, '86234134-0348-5680-ae7f-ec0559225e20'::uuid, 'deb1c2fa-3aa5-5c81-bd24-c5fbe38020b4'::uuid, 'b2b43714-d510-57f4-8626-0ec171403252'::uuid, '59845de5-e84e-508c-aa97-d9825043fe1a'::uuid, '3baaca55-3c88-5a69-ad89-beec3b7b572e'::uuid, 'eea59574-21fd-534d-9601-6449c6687897'::uuid, 'f4a8e98f-72f2-5c46-8590-1aaaf2dd328a'::uuid, '00e71c20-e7e5-5d8f-8393-613d95e75dc3'::uuid, '174aba43-26a4-5181-823c-badb4564e48d'::uuid, 'a19e63d5-b885-5d3e-a661-adf0c8fe3db1'::uuid, '269b33f2-fc15-5322-ba74-d786d707be40'::uuid, '38ba941b-f3e9-5930-ab07-8f6cf629f10c'::uuid);
  if n <> 29 then raise exception 'attese 29 schede, trovate %', n; end if;
end $$;
